class Solution {
public:
    int maxCount(std::vector<int>& banned, int n, int maxSum) {
        std::unordered_set<int> s(banned.begin(), banned.end());
        int ans = 0, total = 0;
        for (int i = 1; i <= n; ++i) {
            if (!s.count(i)) {
                if (total + i <= maxSum) {
                    total += i;
                    ans++;
                } else break;
            }
        }
        return ans;
    }
};

class Solution {
    public int maxCount(int[] banned, int n, int maxSum) {
        java.util.Set<Integer> set = new java.util.HashSet<>();
        for (int b : banned) set.add(b);
        int ans = 0, total = 0;
        for (int i = 1; i <= n; i++) {
            if (!set.contains(i)) {
                if (total + i <= maxSum) {
                    total += i;
                    ans++;
                } else break;
            }
        }
        return ans;
    }
}

